final:
SECONDS_PER_DAY: int = 86_400


def stamp(ts: int) -> str:
    """Format a Unix timestamp in seconds as HH:MM:SS (UTC, 24-hour, zero-padded)."""
    secs = ts % SECONDS_PER_DAY
    hours, rem = divmod(secs, 3600)
    minutes, seconds = divmod(rem, 60)
    return f"{hours:02d}:{minutes:02d}:{seconds:02d}"


def test_stamp_epoch() -> None:
    assert stamp(0) == "00:00:00"


def test_stamp_one_hour_one_minute_one_second() -> None:
    assert stamp(3661) == "01:01:01"


def test_stamp_last_second_of_day() -> None:
    assert stamp(SECONDS_PER_DAY - 1) == "23:59:59"


def test_stamp_wraps_at_day_boundary() -> None:
    assert stamp(SECONDS_PER_DAY) == "00:00:00"
    assert stamp(SECONDS_PER_DAY + 3661) == "01:01:01"
